class Solution {
  public int maxFixedPoints(int[] nums) {
    int n = nums.length, m = 0;
    long[] keyed = new long[n];
    for (int i = 0; i < n; i++) {
      int v = nums[i], w = i - v;
      if (w >= 0) keyed[m++] = ((long) w << 20) | v;
    }
    java.util.Arrays.sort(keyed, 0, m);
    int[] tails = new int[m];
    int len = 0;
    for (int i = 0; i < m; i++) {
      int v = (int) (keyed[i] & ((1 << 20) - 1));
      int lo = 0, hi = len;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (tails[mid] < v) lo = mid + 1;
        else hi = mid;
      }
      tails[lo] = v;
      if (lo == len) len++;
    }
    return len;
  }
}
